		{ text = "Совратитель, кристалл оракула" },
	},
	bonds = {
		{ id = "takata-steelblade", name = "Таката Стальной Клинок", note = "его командир" },
		{ id = "lord-azrethoc", name = "лорд Азреток", note = "демон, которого он нашел" },
	},
})

Translate("ruRU", "felgur-twocuts", {
	title = "Фелгур Два Пореза",
	subtitle = "Посланец Орды",
	found = "Застава Скитающихся Духов",
	hint = [=[Поговорите с орком, который собирает сведения о кентаврах на Заставе Скитающихся Духов.]=],
	allegiance = "Орда",
