})

Translate("ruRU", "gurda-wildmane", {
	title = "Гурда Буйногривая",
	subtitle = "Посланница к кланам",
	found = "Застава Скитающихся Духов",
	hint = [=[Поговорите с тауренкой на Заставе Скитающихся Духов, которая ищет союза среди кентавров.]=],
	allegiance = "Орда",
	sections = {
		{
			title = "Обзор",
			text = [=[Гурда Буйногривая — {link:tauren}таурен{/link}ка с Заставы Скитающихся Духов, которая знает, что одной силой {link:centaurs}кентавр{/link}ов не одолеть. Ее замысел — обратить их ненависть против них самих. {link:horde}Орда{/link} подружится с одним кланом, выведает его тайны и через него узнает, как победить их всех.]=],
		},
		{
			title = "Значение",
			text = [=[Для {link:tauren}тауренов{/link} {link:centaurs}кентавр{/link}ы — самые давние враги. То, что {link:gurda-ragescar}Гурда{/link} готова вести дела с одним кланом против другого, показывает, как далеко пойдет {link:horde}Орда{/link}, чтобы закончить эту долгую войну.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она предлагает выбрать союзника: клан Маграм, убивая {link:centaurs}кентавр{/link}ов Гелкис, или клан Гелкис, убивая кентавров Маграм.]=],
		},
	},
