	bonds = {
		{ id = "khan-shaka", name = "хан Шака", note = "ее хан" },
		{ id = "warug", name = "Варуг", note = "враг ее клана" },
		{ id = "khan-jehn", name = "хан Джен", note = "она добивалась его головы" },
