Translate("ruRU", "warug", {
	title = "Варуг",
	subtitle = "Глашатай клана Маграм",
	found = "Окраина Деревни Маграм",
	hint = [=[Разыщите кентавра Маграм, который говорит от имени своего клана на краю их деревни.]=],
	allegiance = "Клан Маграм",
	sections = {
		{
			title = "Обзор",
			text = [=[Варуг говорит от имени клана Маграм с теми немногими чужаками, которые заслужили право его слушать. Он громогласен, жесток и горд. Клану Маграм не нужна защита, говорит он, — ни от Терадрас, ни от кого бы то ни было, потому что они сильнее всех. Он смеется, когда убивает, и велит другим делать то же, чтобы враги видели, как они слабы.]=],
		},
		{
			title = "Значение",
			text = [=[Варуг — воплощенный символ веры клана Маграм: сила прежде веры и смех над мертвыми. Он же — доказательство того, что клан Маграм, при всем своем презрении, примет помощь чужаков, когда это ему на руку.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он испытывает чужаков по числу убитых ими {link:centaurs}кентавр{/link}ов Гелкис.
• Он посылает их разбить слезы Терадрас, которые копит клан Гелкис.
• Он требует смерти хана клана Гелкис, Шаки, и хана клана Мародин, Храты.
• Когда-то он убил {link:gnomes}гном{/link}а-торговца, приехавшего в {link:desolace}Пустоши{/link}, но оставил себе игрушку с его повозки, потому что она его рассмешила.]=],
		},
	},
	chapters = {
		{
			title = "Друг клана Маграм",
			hint = "Заслужите уважение глашатая клана Маграм.",
			text = [=[{link:centaurs}Кентавры{/link} Маграм не говорят со слабыми. Они их убивают. Варуг не желал сказать ни слова, пока кентавры Гелкис не начинали рыдать при имени чужака. Тогда он допускал, что чужак, быть может, силен, как Маграм, и что, пожалуй, Маграм и чужак могли бы стать друзьями.]=],
		},
		{
			title = "Слезы Терадрас",
			hint = "Разбейте то, что, как верит клан Гелкис, его защищает.",
			text = [=[В пещере в своей деревне клан Гелкис хранил кристаллы, которые звал слезами Терадрас. Варуг хотел, чтобы их разбили, а осколки принесли ему. Если слезы разобьются, говорил он, клан Гелкис поймет, что мать ему не поможет и даже не заплачет, когда Маграм его раздавит.]=],
		},
